const cfg = { proxy: "127.0.0.1", port: 7897 };
const js = [
  "const http=require('http');",
  "const cfg=" + JSON.stringify(cfg) + ";",
  "const UA='Mozilla/5.0 Chrome/155';",
  "function get(u,acc){return new Promise(function(resolve,reject){",
  "  const pu=new URL(u);",
  "  http.get({host:cfg.proxy,port:cfg.port,path:u,headers:{Host:pu.host,'User-Agent':UA,'Accept':acc||'application/rss+xml'}},function(res){",
  "    const c=[];res.on('data',function(d){c.push(d)});",
  "    res.on('end',function(){resolve({status:res.statusCode, body:Buffer.concat(c).toString('utf8')})});",
  "  }).on('error',reject);",
  "});}",
  "(async function(){",
  "  const r=await get('https://hnrss.org/show?points=100');",
  "  const i=r.body.indexOf('<item>');",
  "  console.log('RAW first item:');",
  "  console.log(r.body.substring(i, i+900));",
  "})();",
].join("\n");
await tools.write({ file_path: "C:/Users/jjq21/AppData/Local/Temp/ofm-hnr3.cjs", content: js });
const f = "C:/Users/jjq21/AppData/Local/Temp/ofm-hnr3.cjs";
const r = await tools.pwsh({ command: "node " + JSON.stringify(f), description: "Inspect raw HN RSS item structure", timeoutMs: 200000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text).slice(0, 3000) : JSON.stringify(r).slice(0, 2000));
